module TranTuanNoiThat
  module TamPro

    VERSION = '1.9.102'.freeze
    PLUGIN_NAME = 'TRáº¦N TUáº¤N Ná»˜I THáº¤T - Táº¥m'.freeze

    @dialog_thickness = nil
    @dialog_rename = nil
