    def self.thickness_rows
      scan_objects.map do |e|
        info = thickness_info(e)
        next unless info

        {
          id: entity_key(e),
          name: object_name(e),
          type: object_type(e),
          thickness: info[:thickness],
          d1: info[:dims][0],
          d2: info[:dims][1],
          d3: info[:dims][2]
        }
      end.compact
    end

